window.LAB_DATA = {"grammar":[{"id":"basics","title":"Satzbau, Fragen & Verneinung","sub":"Die Grundlagen wieder sicher anwenden.","rule":"Ein englischer Aussagesatz folgt meist Subjekt + Verb + Objekt. Bei Fragen und Verneinungen im simple present und simple past hilft do/does/did. Nach dem Hilfsverb steht die Grundform.","forms":["He plays football. → Does he play football?","She does not play. / She doesn’t play.","They visited London. → Did they visit London?","Bei be und Modalverben kein do: Are you ready? Can she swim?","Ort steht normalerweise vor Zeit: We met at school yesterday."],"examples":[["She doesn’t like coffee.","doesn’t trägt bereits die Form für he/she/it. Deshalb like, nicht likes."],["We practise in the library every Friday.","Ort vor Zeit. Häufigkeitsadverbien stehen meist vor dem Vollverb: She often reads."]],"trap":"Nicht: Did you went? Richtig: Did you go? Nationalitäten schreibt man groß: British, German.","years":[2022,2024]},{"id":"tenses","title":"Zeiten: Gegenwart & Vergangenheit","sub":"Simple past, present perfect und Verlaufsformen.","rule":"Wähle die Zeit nach der Bedeutung. Eine abgeschlossene Vergangenheit mit Zeitpunkt braucht simple past. Eine Verbindung zu jetzt braucht oft present perfect. Progressive betont einen Verlauf.","forms":["Simple present: I work / she works. Gewohnheiten und Fakten.","Present progressive: am/is/are + -ing. Gerade im Verlauf.","Simple past: worked / went. Abgeschlossen, z. B. yesterday, in 2020.","Past progressive: was/were + -ing. Im Verlauf zu einem Zeitpunkt in der Vergangenheit.","Present perfect: have/has + past participle. Ergebnis/Erfahrung bis jetzt.","Present perfect progressive: have/has been + -ing. Tätigkeit dauert bis jetzt an.","Past perfect: had + past participle. War vor einem anderen vergangenen Ereignis passiert."],"examples":[["I have lived here for five years.","Ich wohne seit fünf Jahren hier und noch immer."],["While she was travelling, it started to snow.","Die Reise war im Verlauf; der Schnee setzte ein."]],"trap":"Nicht jede deutsche Vergangenheitsform wird past perfect. „Ten years ago“ allein verlangt meist simple past. Since nennt den Beginn, for die Dauer.","years":[2021,2022,2023,2024,2025]},{"id":"future","title":"Zukunft ausdrücken","sub":"Will, going to und feste Verabredungen.","rule":"Will passt zu spontanen Entscheidungen, Versprechen und neutralen Vorhersagen. Going to drückt Pläne oder Vorhersagen auf Grundlage sichtbarer Anzeichen aus. Present progressive beschreibt feste Vereinbarungen.","forms":["will + Grundform: I will help you.","am/is/are going to + Grundform: We are going to revise.","Present progressive: I am meeting Sam at six.","Nach if und when für die Zukunft meist simple present: If it rains, we will stay inside."],"examples":[["I hope the project will help people.","Hoffnung/Vorhersage für die Zukunft."],["Look at those clouds. It is going to rain.","Die Vorhersage stützt sich auf sichtbare Anzeichen."]],"trap":"Kein automatisches will in jedem Nebensatz: When I arrive, I will call you.","years":[2024,2025]},{"id":"conditionals","title":"If-Sätze","sub":"Reale Chancen, Vorstellungen und verpasste Chancen.","rule":"Entscheide zuerst: Ist die Bedingung realistisch, nur vorgestellt oder in der Vergangenheit nicht mehr veränderbar?","forms":["Typ I: if + simple present → will + Grundform.","Typ II: if + simple past → would + Grundform.","Typ III: if + past perfect → would have + past participle.","Steht der if-Satz zuerst, setzt du ein Komma."],"examples":[["If I had more time, I would read more.","Vorstellung in Gegenwart/Zukunft (Typ II)."],["If I had studied, I would have passed.","Vergangenheit lässt sich nicht mehr ändern (Typ III)."]],"trap":"In den normalen Bedingungssatz gehört kein would: If we had trained, …","years":[2021,2022,2023,2024]},{"id":"reported","title":"Indirekte Rede","sub":"Aussagen aus einer vergangenen Perspektive wiedergeben.","rule":"Nach einem reporting verb in der Vergangenheit verschieben sich die Zeiten häufig zurück (backshift). Pronomen und Zeitangaben müssen zur neuen Perspektive passen.","forms":["present → past: “I am tired.” → She said she was tired.","past / present perfect → past perfect: “I have finished.” → He said he had finished.","will → would; can → could; may → might.","past perfect bleibt past perfect.","Indirekte Fragen: Aussagesatzstellung. She asked where I lived."],"examples":[["“I will help.” → He said he would help.","will wird bei backshift zu would."],["“I have changed.” → She said she had changed.","have changed wird zu had changed."]],"trap":"Backshift ist nicht immer zwingend, etwa bei weiterhin gültigen Aussagen. Achte im Test auf Erzählperspektive und Kontext.","years":[2021,2022,2025]},{"id":"passive","title":"Das Passiv","sub":"Wenn wichtig ist, was passiert.","rule":"Im Passiv wird die betroffene Person oder Sache zum Subjekt. Die passende Form von be zeigt die Zeit an; das past participle bleibt gleich.","forms":["Simple present: is/are + past participle.","Simple past: was/were + past participle.","Present perfect: has/have been + past participle.","Modalverb: can/must + be + past participle.","Die handelnde Person wird bei Bedarf mit by genannt."],"examples":[["Books were delivered by drones.","Die Bücher wurden geliefert."],["The bridge was built in 1937.","build → built: unregelmäßiges past participle."]],"trap":"Nicht: The books delivered by drones (als vollständiger Satz). Es fehlt were/are.","years":[2022,2023,2024]},{"id":"ing","title":"Gerund oder Infinitiv?","sub":"Enjoy doing, want to do, look forward to doing.","rule":"Nach Präpositionen steht ein Verb als -ing-Form. Manche Verben verlangen -ing, andere einen Infinitiv. Lerne die Verbindung zusammen mit dem Verb.","forms":["enjoy / avoid / finish + -ing.","want / decide / hope / mean (= beabsichtigen) + to + Grundform.","dream of / look forward to / keep someone from + -ing.","want someone to do something: I want you to come.","let / make someone + Grundform (Aktiv): Let me go."],"examples":[["I look forward to seeing you.","To ist hier eine Präposition, kein Infinitivsignal."],["She stopped reading. / She stopped to read.","Sie hörte auf zu lesen. / Sie hielt an, um zu lesen."],["Remember locking the door. / Remember to lock the door.","Sich erinnern, abgeschlossen zu haben. / Daran denken, noch abzuschließen."]],"trap":"Nicht: I want that you help. Richtig: I want you to help.","years":[2021,2022,2023,2024,2025]},{"id":"participles","title":"Partizipien & verkürzte Sätze","sub":"Present participle und past participle unterscheiden.","rule":"Partizipien verkürzen Relativ- oder adverbiale Nebensätze. Die -ing-Form hat meist aktive Bedeutung, das past participle meist passive Bedeutung.","forms":["Aktiv: people who live here → people living here.","Passiv: a book which was written in 2020 → a book written in 2020.","Gleiches Subjekt bei adverbialen Verkürzungen: Walking home, I met Sam.","Vorzeitigkeit: Having finished her work, she went home."],"examples":[["The trip, tracked online, attracted attention.","Die Reise wurde online verfolgt: passive Bedeutung."],["He set a record, beating the previous one.","Er überbot selbst den Rekord: aktive Bedeutung."]],"trap":"Bei „Walking home, the rain started“ scheint der Regen nach Hause zu gehen. Das gedachte Subjekt muss passen.","years":[2022,2024,2025]},{"id":"modals","title":"Modalverben & Ersatzformen","sub":"Können, dürfen und müssen sauber unterscheiden.","rule":"Can, must und may haben nicht alle Zeitformen. Verwende passende Ersatzformen. Fähigkeit, Erlaubnis und Verpflichtung sind unterschiedliche Bedeutungen.","forms":["Fähigkeit: can → be able to. Vergangenheit: was/were able to.","Erlaubnis: may/can → be allowed to.","Verpflichtung: must → have to. Vergangenheit: had to.","Verbot: must not / mustn’t.","Keine Notwendigkeit: do not have to / need not."],"examples":[["She had to leave.","Sie musste gehen."],["He was able to finish.","Es gelang ihm, fertig zu werden."],["You don’t have to come.","Du musst nicht kommen. Du darfst aber."]],"trap":"Mustn’t bedeutet „nicht dürfen“, nicht „nicht müssen“. Could ist möglich für allgemeine vergangene Fähigkeiten; einzelne Erfolge oft was able to.","years":[2021,2022,2023,2025]},{"id":"comparison","title":"Adjektive, Adverbien & Vergleiche","sub":"Fast, well, better und the longest.","rule":"Adjektive beschreiben Personen/Sachen; Adverbien beschreiben Tätigkeiten oder verstärken Adjektive. Viele Adverbien enden auf -ly, aber nicht alle.","forms":["quick → quickly; extreme → extremely.","fast → fast; good → well; hard → hard (hardly = kaum).","short → shorter → the shortest.","happy → happier → the happiest.","interesting → more interesting → the most interesting.","good/well → better → best; bad → worse → worst.","Vergleich verstärken: much / far / a lot better."],"examples":[["She is extremely happy.","Extremely verstärkt das Adjektiv happy."],["The deeper you go, the greater the pressure.","Je … desto … verwendet zwei Komparative."]],"trap":"Nicht: more better, fastly oder the most fastest. Nach be/look/feel steht oft ein Adjektiv: She feels happy.","years":[2021,2022,2024,2025]},{"id":"quantifiers","title":"Mengen, Artikel & Pronomen","sub":"Much/many, little/few, a/an und Plural.","rule":"Frage zuerst: Ist das Nomen zählbar? Many und few stehen bei zählbaren Nomen im Plural; much und little bei nicht zählbaren Nomen.","forms":["many books / few books; much time / little time.","a few / a little = einige / ein wenig; few / little = wenige / wenig.","some meist positiv, any oft in Fragen und Verneinungen.","Berufe brauchen a/an: She is a teacher. He is an actor.","this book → these books; that book → those books.","Allgemein: Most people … Spezifisch: Most of the people here …"],"examples":[["I don’t have any questions.","Any im verneinten Satz."],["We have very little time.","Time ist hier nicht zählbar."]],"trap":"Information, advice und homework sind normalerweise nicht zählbar: some advice, nicht advices. A/an richtet sich nach dem Laut: a university, an hour.","years":[2021,2022,2023,2024]},{"id":"prepositions","title":"Präpositionen & Verknüpfungen","sub":"During/while, since/for und because/because of.","rule":"Achte darauf, was nach dem Ausdruck kommt. Eine Präposition steht vor einer Nomengruppe oder -ing-Form. Eine Konjunktion verbindet vollständige Teilsätze.","forms":["during + Nomen: during the lesson.","while + Subjekt + Verb: while I was studying.","because + Satz; because of + Nomen.","although + Satz; despite / in spite of + Nomen oder -ing.","since + Beginn; for + Dauer.","Feste Verbindungen: good at, interested in, depend on."],"examples":[["During the trip, I read a book.","Trip ist ein Nomen."],["While we were travelling, I read.","We were travelling ist ein vollständiger Teilsatz."]],"trap":"Nicht: in spite the rain. Richtig: in spite of the rain oder despite the rain.","years":[2021,2022,2023,2025]},{"id":"relatives","title":"Relativsätze","sub":"Who, which, that und whose.","rule":"Relativsätze ergänzen Informationen zu einem Nomen. Who bezieht sich auf Menschen, which auf Dinge; whose zeigt Besitz an.","forms":["The girl who lives next door is nice.","The book which/that I read was exciting.","The pilot, whose parents also fly, set a record.","Zusatzinformation mit Kommas: London, which is in England, …","In solchen non-defining relative clauses kein that und kein Weglassen des Pronomens."],"examples":[["The fee, which includes meals, is high.","Zusatzinformation nach Komma → which."],["A student whose phone was lost asked for help.","Whose phone = deren/dessen Telefon."]],"trap":"Who’s heißt who is oder who has. Besitz wird mit whose ausgedrückt.","years":[2022,2024]},{"id":"possessive","title":"Genitiv & typische Stolperstellen","sub":"Apostrophe, unregelmäßige Formen und false friends.","rule":"Der s-Genitiv zeigt Zugehörigkeit. Unterscheide Singular und Plural. Lerne häufige unregelmäßige Verbformen in Dreierreihen.","forms":["Singular: the scientist’s idea.","Regelmäßiger Plural auf -s: the scientists’ ideas.","Unregelmäßiger Plural: the children’s books.","fly – flew – flown; write – wrote – written; go – went – gone.","bekommen = get/receive; become = werden.","Englische Zahlen: 1,700 (eintausendsiebenhundert), 1.7 (eins Komma sieben)."],"examples":[["The students’ interests are different.","Mehrere Schülerinnen/Schüler → Apostroph nach dem Plural-s."],["She received a book.","Sie bekam ein Buch, sie wurde keines."]],"trap":"Its ist das Possessivwort, it’s heißt it is/it has. Für „die meisten Menschen“: most people.","years":[2021,2023,2024,2025]}],"questions":[{"id":"g-basics-0","topic":"basics","prompt":"___ she play tennis every week?","answers":["Does"],"explanation":"Bei she im simple present: Does + Subjekt + Grundform.","source":"Eigene Grundlagenübung","year":0},{"id":"g-basics-1","topic":"basics","prompt":"They did not ___ (go) to school yesterday.","answers":["go"],"explanation":"Did markiert die Vergangenheit; go bleibt in der Grundform.","source":"Eigene Grundlagenübung","year":0},{"id":"g-basics-2","topic":"basics","prompt":"Setze die Orts- und Zeitangabe ein: We meet ___ . (every Monday / at school)","answers":["at school every Monday"],"explanation":"Normalerweise steht Ort vor Zeit.","source":"Eigene Grundlagenübung","year":0},{"id":"g-tenses-3","topic":"tenses","prompt":"We ___ (visit) London in 2022.","answers":["visited"],"explanation":"In 2022 ist ein abgeschlossener Zeitpunkt: simple past.","source":"Eigene Grundlagenübung","year":0},{"id":"g-tenses-4","topic":"tenses","prompt":"She ___ (work) here since 2020 and still enjoys her job.","answers":["has worked","has been working"],"explanation":"Die Tätigkeit verbindet Vergangenheit und Gegenwart.","source":"Eigene Grundlagenübung","year":0},{"id":"g-tenses-5","topic":"tenses","prompt":"While I ___ (read), my phone rang.","answers":["was reading"],"explanation":"Längerer Vorgang im Hintergrund: past progressive.","source":"Eigene Grundlagenübung","year":0},{"id":"g-future-6","topic":"future","prompt":"I promise I ___ (help) you tomorrow.","answers":["will help","'ll help"],"explanation":"Ein Versprechen wird hier mit will formuliert.","source":"Eigene Grundlagenübung","year":0},{"id":"g-future-7","topic":"future","prompt":"Look at those dark clouds! It ___ (rain). Use going to.","answers":["is going to rain"],"explanation":"Sichtbare Anzeichen: going to.","source":"Eigene Grundlagenübung","year":0},{"id":"g-future-8","topic":"future","prompt":"When she ___ (arrive) tomorrow, we will start.","answers":["arrives"],"explanation":"Im when-Satz für die Zukunft steht hier simple present.","source":"Eigene Grundlagenübung","year":0},{"id":"g-conditionals-9","topic":"conditionals","prompt":"If it rains, we ___ (stay) at home.","answers":["will stay","'ll stay"],"explanation":"Typ I: reale Möglichkeit → will + Grundform.","source":"Eigene Grundlagenübung","year":0},{"id":"g-conditionals-10","topic":"conditionals","prompt":"If I had a car, I ___ (drive) to school.","answers":["would drive","'d drive"],"explanation":"Typ II: Vorstellung → would + Grundform.","source":"Eigene Grundlagenübung","year":0},{"id":"g-conditionals-11","topic":"conditionals","prompt":"If she had left earlier, she ___ (catch) the bus.","answers":["would have caught","'d have caught"],"explanation":"Typ III: would have + past participle, catch → caught.","source":"Eigene Grundlagenübung","year":0},{"id":"g-reported-12","topic":"reported","prompt":"“I will call.” He said that he ___ call. Use backshift.","answers":["would"],"explanation":"Will wird in der indirekten Rede mit backshift zu would.","source":"Eigene Grundlagenübung","year":0},{"id":"g-reported-13","topic":"reported","prompt":"“I have finished.” She said she ___ . Use backshift.","answers":["had finished"],"explanation":"Present perfect wird past perfect.","source":"Eigene Grundlagenübung","year":0},{"id":"g-reported-14","topic":"reported","prompt":"“Where do you live?” She asked where I ___ . Use backshift.","answers":["lived"],"explanation":"Indirekte Frage: keine do-Umschreibung, normale Satzstellung.","source":"Eigene Grundlagenübung","year":0},{"id":"g-passive-15","topic":"passive","prompt":"The bridge ___ (build) in 1937.","answers":["was built"],"explanation":"Vergangenheit und Passiv: was + built.","source":"Eigene Grundlagenübung","year":0},{"id":"g-passive-16","topic":"passive","prompt":"These rooms ___ (clean) every day.","answers":["are cleaned"],"explanation":"Regelmäßig und Plural: are + cleaned.","source":"Eigene Grundlagenübung","year":0},{"id":"g-passive-17","topic":"passive","prompt":"The letter was written ___ Mia.","answers":["by"],"explanation":"By nennt die handelnde Person im Passiv.","source":"Eigene Grundlagenübung","year":0},{"id":"g-ing-18","topic":"ing","prompt":"I look forward to ___ (see) you.","answers":["seeing"],"explanation":"Look forward to + -ing.","source":"Eigene Grundlagenübung","year":0},{"id":"g-ing-19","topic":"ing","prompt":"She wants him ___ (help).","answers":["to help"],"explanation":"Want + Person + to-infinitive.","source":"Eigene Grundlagenübung","year":0},{"id":"g-ing-20","topic":"ing","prompt":"He stopped ___ (smoke): he gave up cigarettes.","answers":["smoking"],"explanation":"Stop + -ing heißt mit einer Tätigkeit aufhören.","source":"Eigene Grundlagenübung","year":0},{"id":"g-participles-21","topic":"participles","prompt":"The girl ___ (stand) at the door is my sister.","answers":["standing"],"explanation":"Sie steht selbst dort: aktive -ing-Form.","source":"Eigene Grundlagenübung","year":0},{"id":"g-participles-22","topic":"participles","prompt":"The book, ___ (write) in English, is popular.","answers":["written"],"explanation":"Das Buch wurde geschrieben: past participle.","source":"Eigene Grundlagenübung","year":0},{"id":"g-participles-23","topic":"participles","prompt":"He broke the record, ___ (beat) the previous champion.","answers":["beating"],"explanation":"Er übertraf den Champion selbst: aktive Form.","source":"Eigene Grundlagenübung","year":0},{"id":"g-modals-24","topic":"modals","prompt":"Yesterday we ___ (must) take a test.","answers":["had to"],"explanation":"Must in der Vergangenheit → had to.","source":"Eigene Grundlagenübung","year":0},{"id":"g-modals-25","topic":"modals","prompt":"After several attempts, she ___ open the door. (be able to)","answers":["was able to"],"explanation":"Ein einzelner Erfolg in der Vergangenheit.","source":"Eigene Grundlagenübung","year":0},{"id":"g-modals-26","topic":"modals","prompt":"You ___ touch the exhibits. It is forbidden.","answers":["must not","mustn't"],"explanation":"Verbot → must not, nicht do not have to.","source":"Eigene Grundlagenübung","year":0},{"id":"g-comparison-27","topic":"comparison","prompt":"She runs very ___ (fast).","answers":["fast"],"explanation":"Fast ist Adjektiv und Adverb; fastly gibt es hier nicht.","source":"Eigene Grundlagenübung","year":0},{"id":"g-comparison-28","topic":"comparison","prompt":"This is the ___ (bad) day of the week.","answers":["worst"],"explanation":"Unregelmäßiger Superlativ: bad → worse → worst.","source":"Eigene Grundlagenübung","year":0},{"id":"g-comparison-29","topic":"comparison","prompt":"He speaks English ___ (good).","answers":["well"],"explanation":"Das Verb speaks wird durch das Adverb well beschrieben.","source":"Eigene Grundlagenübung","year":0},{"id":"g-quantifiers-30","topic":"quantifiers","prompt":"How ___ books have you read?","answers":["many"],"explanation":"Books ist zählbar und Plural.","source":"Eigene Grundlagenübung","year":0},{"id":"g-quantifiers-31","topic":"quantifiers","prompt":"She is ___ English teacher.","answers":["an"],"explanation":"Berufsbezeichnung mit Artikel; English beginnt mit Vokallaut.","source":"Eigene Grundlagenübung","year":0},{"id":"g-quantifiers-32","topic":"quantifiers","prompt":"I have very ___ time left, so I must hurry.","answers":["little"],"explanation":"Time ist nicht zählbar; little bedeutet wenig.","source":"Eigene Grundlagenübung","year":0},{"id":"g-prepositions-33","topic":"prepositions","prompt":"We stayed indoors ___ the storm. (during / while)","answers":["during"],"explanation":"Vor der Nomengruppe the storm steht during.","source":"Eigene Grundlagenübung","year":0},{"id":"g-prepositions-34","topic":"prepositions","prompt":"She has lived here ___ 2021. (since / for)","answers":["since"],"explanation":"2021 ist der Beginn, keine Dauer.","source":"Eigene Grundlagenübung","year":0},{"id":"g-prepositions-35","topic":"prepositions","prompt":"He is very good ___ maths.","answers":["at"],"explanation":"Feste Verbindung: good at something.","source":"Eigene Grundlagenübung","year":0},{"id":"g-relatives-36","topic":"relatives","prompt":"This is the teacher ___ helped me.","answers":["who","that"],"explanation":"Bezug auf eine Person in einem defining relative clause.","source":"Eigene Grundlagenübung","year":0},{"id":"g-relatives-37","topic":"relatives","prompt":"The bridge, ___ opened in 1937, is famous.","answers":["which"],"explanation":"Non-defining relative clause mit Komma: which, nicht that.","source":"Eigene Grundlagenübung","year":0},{"id":"g-relatives-38","topic":"relatives","prompt":"The girl ___ brother is in my class waved at me.","answers":["whose"],"explanation":"Besitzbeziehung: whose brother.","source":"Eigene Grundlagenübung","year":0},{"id":"g-possessive-39","topic":"possessive","prompt":"These are the ___ books. (children)","answers":["children’s","children's"],"explanation":"Unregelmäßiger Plural ohne s → Apostroph + s.","source":"Eigene Grundlagenübung","year":0},{"id":"g-possessive-40","topic":"possessive","prompt":"The plane ___ (fly) over the city yesterday.","answers":["flew"],"explanation":"Simple past von fly ist flew.","source":"Eigene Grundlagenübung","year":0},{"id":"g-possessive-41","topic":"possessive","prompt":"Translate bekommen: You will ___ a letter tomorrow.","answers":["get","receive"],"explanation":"Become bedeutet werden; bekommen = get/receive.","source":"Eigene Grundlagenübung","year":0},{"id":"o2021-1","year":2021,"topic":"tenses","prompt":"New Jersey ___ one of the top high school football states for many years.","answers":["has been"],"explanation":"For many years reicht hier bis in die Gegenwart: present perfect.","source":"Nach Originaltest 2021 · Use of English · Item 1"},{"id":"o2021-2","year":2021,"topic":"comparison","prompt":"The number of teenagers taking part is falling really ___ . (fast)","answers":["fast"],"explanation":"Fast bleibt als Adverb unverändert.","source":"Nach Originaltest 2021 · Use of English · Item 2"},{"id":"o2021-3","year":2021,"topic":"possessive","prompt":"Schreibe 1700 mit englischem Tausendertrennzeichen.","answers":["1,700"],"explanation":"Im Englischen trennt das Komma die Tausender.","source":"Nach Originaltest 2021 · Use of English · Item 3"},{"id":"o2021-4","year":2021,"topic":"comparison","prompt":"Only three other states were even ___ affected. (bad)","answers":["worse"],"explanation":"Unregelmäßiger Komparativ: bad → worse.","source":"Nach Originaltest 2021 · Use of English · Item 4"},{"id":"o2021-5","year":2021,"topic":"prepositions","prompt":"___ New Jersey’s proud football tradition, participation is falling. (trotz)","answers":["in spite of","despite"],"explanation":"Vor einer Nomengruppe: despite oder in spite of.","source":"Nach Originaltest 2021 · Use of English · Item 5"},{"id":"o2021-6","year":2021,"topic":"tenses","prompt":"In 2009, a record 1 million athletes ___ part. (take)","answers":["took"],"explanation":"Abgeschlossener Zeitpunkt: simple past.","source":"Nach Originaltest 2021 · Use of English · Item 6"},{"id":"o2021-7","year":2021,"topic":"quantifiers","prompt":"Coach Mike Warnock is also ___ . (teacher)","answers":["a teacher"],"explanation":"Berufsangaben benötigen den unbestimmten Artikel.","source":"Nach Originaltest 2021 · Use of English · Item 7"},{"id":"o2021-8","year":2021,"topic":"conditionals","prompt":"If there had been enough players, they ___ the game. (not / cancel)","answers":["would not have cancelled","wouldn't have cancelled","would not have canceled","wouldn't have canceled"],"explanation":"Typ III: would not have + past participle.","source":"Nach Originaltest 2021 · Use of English · Item 8"},{"id":"o2021-9","year":2021,"topic":"prepositions","prompt":"He has handed out questionnaires ___ the past 16 years.","answers":["for"],"explanation":"16 Jahre sind eine Zeitspanne → for.","source":"Nach Originaltest 2021 · Use of English · Item 9"},{"id":"o2021-10","year":2021,"topic":"possessive","prompt":"He wants to learn about his ___ interests. (students, Plural-Genitiv)","answers":["students’","students'"],"explanation":"Regelmäßiger Plural auf s: Apostroph nach dem s.","source":"Nach Originaltest 2021 · Use of English · Item 10"},{"id":"o2021-11","year":2021,"topic":"quantifiers","prompt":"You don’t play ___ sports this season, do you?","answers":["any"],"explanation":"Im verneinten Satz steht hier any.","source":"Nach Originaltest 2021 · Use of English · Item 11"},{"id":"o2021-12","year":2021,"topic":"ing","prompt":"What’s keeping you ___ football? (play)","answers":["from playing"],"explanation":"Keep someone from + -ing.","source":"Nach Originaltest 2021 · Use of English · Item 12"},{"id":"o2021-13","year":2021,"topic":"ing","prompt":"Another coach remembers ___ a parent for weeks. (ask)","answers":["asking"],"explanation":"Er erinnert sich an eine vergangene Handlung: remember + -ing.","source":"Nach Originaltest 2021 · Use of English · Item 13"},{"id":"o2021-14","year":2021,"topic":"reported","prompt":"He told her that football ___ him a lot. (will / help, backshift)","answers":["would help"],"explanation":"Will → would nach told.","source":"Nach Originaltest 2021 · Use of English · Item 14"},{"id":"o2021-15","year":2021,"topic":"prepositions","prompt":"He wants to get better ___ basketball.","answers":["at"],"explanation":"Feste Verbindung: good/better at.","source":"Nach Originaltest 2021 · Use of English · Item 15"},{"id":"o2022-1","year":2022,"topic":"basics","prompt":"The ___ runner Susannah Gill set a record. (british)","answers":["British"],"explanation":"Nationalitäten werden großgeschrieben.","source":"Nach Originaltest 2022 · Use of English · Item 1","caseSensitive":true},{"id":"o2022-2","year":2022,"topic":"comparison","prompt":"She finished in the ___ time by a woman athlete. (fast)","answers":["fastest"],"explanation":"Superlativ nach the: fastest.","source":"Nach Originaltest 2022 · Use of English · Item 2"},{"id":"o2022-3","year":2022,"topic":"participles","prompt":"She braved extreme temperatures before ___ the event in Miami. (finish)","answers":["finishing"],"explanation":"Nach before kann eine verkürzte -ing-Konstruktion stehen.","source":"Nach Originaltest 2022 · Use of English · Item 3"},{"id":"o2022-4","year":2022,"topic":"prepositions","prompt":"___ the week-long challenge, she won almost every race.","answers":["During","Throughout","In"],"explanation":"Vor der Nomengruppe steht eine Präposition.","source":"Nach Originaltest 2022 · Use of English · Item 4"},{"id":"o2022-5","year":2022,"topic":"tenses","prompt":"Ten years ago, I ___ to get fit. (just / want)","answers":["just wanted"],"explanation":"Ohne Vorvergangenheitsbezug: simple past, nicht had just wanted.","source":"Nach Originaltest 2022 · Use of English · Item 5"},{"id":"o2022-6","year":2022,"topic":"passive","prompt":"Participants are warned ___ the race organisers.","answers":["by"],"explanation":"By nennt im Passiv den Handelnden.","source":"Nach Originaltest 2022 · Use of English · Item 6"},{"id":"o2022-7","year":2022,"topic":"modals","prompt":"They must be able ___ the challenge. (complete)","answers":["to complete"],"explanation":"Be able + to-infinitive.","source":"Nach Originaltest 2022 · Use of English · Item 7"},{"id":"o2022-8","year":2022,"topic":"tenses","prompt":"Fewer than 200 people ___ the marathon since 2003. (finish)","answers":["have finished"],"explanation":"Since 2003 bis jetzt → present perfect.","source":"Nach Originaltest 2022 · Use of English · Item 8"},{"id":"o2022-9","year":2022,"topic":"relatives","prompt":"The entry fee, ___ pays for accommodation, is high.","answers":["which"],"explanation":"Non-defining relative clause nach Komma: which.","source":"Nach Originaltest 2022 · Use of English · Item 9"},{"id":"o2022-10","year":2022,"topic":"passive","prompt":"The competitors were ___ across the globe. (fly)","answers":["flown"],"explanation":"Past participle im Passiv: flown.","source":"Nach Originaltest 2022 · Use of English · Item 10"},{"id":"o2022-11","year":2022,"topic":"reported","prompt":"Gill admitted that it ___ hard running seven marathons. (be, Vorzeitigkeit)","answers":["had been"],"explanation":"Vorzeitigkeit in indirekter Rede: past perfect.","source":"Nach Originaltest 2022 · Use of English · Item 11"},{"id":"o2022-12","year":2022,"topic":"quantifiers","prompt":"She had very ___ sleep. (few / little)","answers":["little"],"explanation":"Sleep ist nicht zählbar.","source":"Nach Originaltest 2022 · Use of English · Item 12"},{"id":"o2022-13","year":2022,"topic":"conditionals","prompt":"If I hadn’t trained every day, I ___ it. (not / win)","answers":["wouldn't have won","would not have won"],"explanation":"Typ III: would have + won.","source":"Nach Originaltest 2022 · Use of English · Item 13"},{"id":"o2022-14","year":2022,"topic":"quantifiers","prompt":"___ people don’t know how hard it is. (die meisten)","answers":["Most"],"explanation":"Bei allgemeinen Aussagen: most people ohne the.","source":"Nach Originaltest 2022 · Use of English · Item 14"},{"id":"o2022-15","year":2022,"topic":"comparison","prompt":"Make sure that you eat ___ . (good)","answers":["well"],"explanation":"Adverb von good: well.","source":"Nach Originaltest 2022 · Use of English · Item 15"},{"id":"o2023-1","year":2023,"topic":"prepositions","prompt":"In 2020, ___ the pandemic, many libraries closed. (during / while)","answers":["during"],"explanation":"Vor einer Nomengruppe: during.","source":"Nach Originaltest 2023 · Use of English · Item 1"},{"id":"o2023-2","year":2023,"topic":"modals","prompt":"Because of the closures, students ___ to visit the libraries. (be able, Vergangenheit verneint)","answers":["weren’t able","weren't able","were not able"],"explanation":"Die Möglichkeit fehlte: were not able, nicht did not have to.","source":"Nach Originaltest 2023 · Use of English · Item 2"},{"id":"o2023-3","year":2023,"topic":"ing","prompt":"Families stopped ___ free reading material. (get)","answers":["getting"],"explanation":"Stop + -ing: Sie bekamen kein kostenloses Material mehr.","source":"Nach Originaltest 2023 · Use of English · Item 3"},{"id":"o2023-4","year":2023,"topic":"passive","prompt":"Books ___ by drones. (deliver, simple past)","answers":["were delivered"],"explanation":"Plural-Passiv der Vergangenheit: were delivered.","source":"Nach Originaltest 2023 · Use of English · Item 4"},{"id":"o2023-5","year":2023,"topic":"quantifiers","prompt":"Kelly Passek is ___ at a middle school. (librarian)","answers":["a librarian"],"explanation":"Berufsbezeichnung mit a.","source":"Nach Originaltest 2023 · Use of English · Item 5"},{"id":"o2023-6","year":2023,"topic":"tenses","prompt":"She ___ there for over 15 years now. (work, progressive)","answers":["has been working"],"explanation":"Anhaltende Tätigkeit bis jetzt: present perfect progressive.","source":"Nach Originaltest 2023 · Use of English · Item 6"},{"id":"o2023-7","year":2023,"topic":"tenses","prompt":"The school ___ in the spring of 2020. (close)","answers":["closed","was closed","had to close"],"explanation":"Abgeschlossener Zeitpunkt → simple past; auch Passiv ist möglich.","source":"Nach Originaltest 2023 · Use of English · Item 7"},{"id":"o2023-8","year":2023,"topic":"ing","prompt":"She wanted ___ have access to books. (her students)","answers":["her students to"],"explanation":"Want + Person + to-infinitive.","source":"Nach Originaltest 2023 · Use of English · Item 8"},{"id":"o2023-9","year":2023,"topic":"possessive","prompt":"In Kelly ___ hometown, drones deliver food. (Passek)","answers":["Passek’s","Passek's"],"explanation":"Singular-Genitiv: Apostroph + s.","source":"Nach Originaltest 2023 · Use of English · Item 9"},{"id":"o2023-10","year":2023,"topic":"tenses","prompt":"She ___ the service before the pandemic started. (use)","answers":["had used"],"explanation":"Nutzung fand vor einem vergangenen Ereignis statt: past perfect.","source":"Nach Originaltest 2023 · Use of English · Item 10"},{"id":"o2023-11","year":2023,"topic":"ing","prompt":"It could work for ___ books to students. (deliver)","answers":["delivering"],"explanation":"Nach Präposition for steht -ing.","source":"Nach Originaltest 2023 · Use of English · Item 11"},{"id":"o2023-12","year":2023,"topic":"quantifiers","prompt":"Passek put ___ books in a box. (this im Plural)","answers":["these"],"explanation":"This → these im Plural.","source":"Nach Originaltest 2023 · Use of English · Item 12"},{"id":"o2023-13","year":2023,"topic":"possessive","prompt":"The drone ___ to the delivery location. (fly, simple past)","answers":["flew"],"explanation":"Fly → flew → flown.","source":"Nach Originaltest 2023 · Use of English · Item 13"},{"id":"o2023-14","year":2023,"topic":"possessive","prompt":"They were the first to ___ a library book by drone. (bekommen)","answers":["get","receive"],"explanation":"Get/receive bedeutet bekommen; become bedeutet werden.","source":"Nach Originaltest 2023 · Use of English · Item 14"},{"id":"o2023-15","year":2023,"topic":"conditionals","prompt":"If the school ___ used the system, the kids wouldn’t have received books.","answers":["hadn’t","hadn't","had not"],"explanation":"Typ III: if + past perfect.","source":"Nach Originaltest 2023 · Use of English · Item 15"},{"id":"o2024-1","year":2024,"topic":"comparison","prompt":"Zara was ___ happy. (extreme)","answers":["extremely"],"explanation":"Das Adjektiv happy wird vom Adverb extremely verstärkt.","source":"Nach Originaltest 2024 · Use of English · Item 1"},{"id":"o2024-2","year":2024,"topic":"ing","prompt":"She was happy after ___ a solo flight around the world. (complete)","answers":["completing","having completed","she completed","she had completed"],"explanation":"After + -ing oder after + vollständiger Nebensatz.","source":"Nach Originaltest 2024 · Use of English · Item 2"},{"id":"o2024-3","year":2024,"topic":"ing","prompt":"She had the dream of ___ into the record books. (get)","answers":["getting"],"explanation":"Präposition of + -ing.","source":"Nach Originaltest 2024 · Use of English · Item 3"},{"id":"o2024-4","year":2024,"topic":"passive","prompt":"She landed and ___ by a crowd. (welcome)","answers":["was welcomed"],"explanation":"Simple past passive: was + welcomed.","source":"Nach Originaltest 2024 · Use of English · Item 4"},{"id":"o2024-5","year":2024,"topic":"tenses","prompt":"“I ___ happier in all my life,” she said. (never / be, present perfect)","answers":["have never been"],"explanation":"Erfahrung bis zu diesem Moment: present perfect.","source":"Nach Originaltest 2024 · Use of English · Item 5"},{"id":"o2024-6","year":2024,"topic":"ing","prompt":"She was looking forward to ___ her feet up. (put)","answers":["putting"],"explanation":"Look forward to + -ing. Put verdoppelt t.","source":"Nach Originaltest 2024 · Use of English · Item 6"},{"id":"o2024-7","year":2024,"topic":"comparison","prompt":"Mongolia was the ___ part of the journey. (scary)","answers":["scariest"],"explanation":"Scary → scarier → scariest.","source":"Nach Originaltest 2024 · Use of English · Item 7"},{"id":"o2024-8","year":2024,"topic":"tenses","prompt":"While she ___, she saw no one for miles. (travel)","answers":["was travelling","was traveling"],"explanation":"Längerer Vorgang in der Vergangenheit: past progressive.","source":"Nach Originaltest 2024 · Use of English · Item 8"},{"id":"o2024-9","year":2024,"topic":"conditionals","prompt":"If the machine stopped, I ___ a big problem. (have)","answers":["would have","'d have"],"explanation":"Typ II: if + simple past → would + Grundform.","source":"Nach Originaltest 2024 · Use of English · Item 9"},{"id":"o2024-10","year":2024,"topic":"participles","prompt":"The trip, ___ on her website, was unforgettable. (track)","answers":["tracked"],"explanation":"Die Reise wurde verfolgt: passive Partizipialkonstruktion.","source":"Nach Originaltest 2024 · Use of English · Item 10"},{"id":"o2024-11","year":2024,"topic":"quantifiers","prompt":"I travelled through so ___ countries. (much / many)","answers":["many"],"explanation":"Countries ist zählbarer Plural.","source":"Nach Originaltest 2024 · Use of English · Item 11"},{"id":"o2024-12","year":2024,"topic":"ing","prompt":"My parents said yes and ___ me go on this journey. (erlaubten)","answers":["let"],"explanation":"Let = erlauben, make = dazu bringen/zwingen.","source":"Nach Originaltest 2024 · Use of English · Item 12"},{"id":"o2024-13","year":2024,"topic":"basics","prompt":"I get ___ . (every day / on a plane)","answers":["on a plane every day"],"explanation":"Ort vor Zeit.","source":"Nach Originaltest 2024 · Use of English · Item 13"},{"id":"o2024-14","year":2024,"topic":"ing","prompt":"I want ___ inspire people.","answers":["to"],"explanation":"Want + to-infinitive, nicht want that I.","source":"Nach Originaltest 2024 · Use of English · Item 14"},{"id":"o2024-15","year":2024,"topic":"possessive","prompt":"People should do something with their ___ . (life)","answers":["lives"],"explanation":"Mehrere Menschen mit eigenen Leben: distributiver Plural lives.","source":"Nach Originaltest 2024 · Use of English · Item 15"},{"id":"o2025-1","year":2025,"topic":"participles","prompt":"Dr. Dituri, also ___ as “Dr. Deep Sea”, lived underwater. (know)","answers":["known"],"explanation":"Verkürzter passiver Relativsatz: known.","source":"Nach Originaltest 2025 · Use of English · Item 1"},{"id":"o2025-2","year":2025,"topic":"ing","prompt":"He meant ___ a new world record. (set)","answers":["to set"],"explanation":"Mean im Sinne von beabsichtigen verlangt to-infinitive.","source":"Nach Originaltest 2025 · Use of English · Item 2"},{"id":"o2025-3","year":2025,"topic":"comparison","prompt":"He wanted a record for ___ time spent underwater. (long)","answers":["the longest"],"explanation":"Superlativ mit the: the longest.","source":"Nach Originaltest 2025 · Use of English · Item 3"},{"id":"o2025-4","year":2025,"topic":"participles","prompt":"He set a record, in this way ___ the old one. (beat)","answers":["beating"],"explanation":"Aktive Bedeutung → present participle.","source":"Nach Originaltest 2025 · Use of English · Item 4"},{"id":"o2025-5","year":2025,"topic":"comparison","prompt":"The further you go below the surface, the ___ the pressure. (great)","answers":["greater"],"explanation":"The + Komparativ … the + Komparativ.","source":"Nach Originaltest 2025 · Use of English · Item 5"},{"id":"o2025-6","year":2025,"topic":"reported","prompt":"He added that high pressure ___ people live longer one day. (will / help, backshift)","answers":["would help","could help","might help"],"explanation":"Backshift von will → would; could/might sind im Originalschlüssel ebenfalls zugelassen.","source":"Nach Originaltest 2025 · Use of English · Item 6"},{"id":"o2025-7","year":2025,"topic":"tenses","prompt":"All the time while he ___ underwater, he stayed busy. (live)","answers":["was living"],"explanation":"Zeitgleich andauernder Vorgang in der Vergangenheit.","source":"Nach Originaltest 2025 · Use of English · Item 7"},{"id":"o2025-8","year":2025,"topic":"comparison","prompt":"He continued teaching his students ___ . (virtual)","answers":["virtually"],"explanation":"Das Verb teaching wird durch ein Adverb beschrieben.","source":"Nach Originaltest 2025 · Use of English · Item 8"},{"id":"o2025-9","year":2025,"topic":"modals","prompt":"He ___ be checked every week. (must, Vergangenheit)","answers":["had to"],"explanation":"Vergangenheit von must → had to.","source":"Nach Originaltest 2025 · Use of English · Item 9"},{"id":"o2025-10","year":2025,"topic":"modals","prompt":"He returned to the surface, where he ___ to see the sun again. (war endlich in der Lage)","answers":["was finally able"],"explanation":"Fähigkeit/Möglichkeit, nicht Erlaubnis oder Pflicht.","source":"Nach Originaltest 2025 · Use of English · Item 10"},{"id":"o2025-11","year":2025,"topic":"reported","prompt":"He said that the experience ___ him. (change, backshift)","answers":["had changed"],"explanation":"Die Veränderung war vorher passiert: past perfect.","source":"Nach Originaltest 2025 · Use of English · Item 11"},{"id":"o2025-12","year":2025,"topic":"future","prompt":"“I hope my research ___ to treat illnesses eventually.” (will / help)","answers":["will help"],"explanation":"Direkte Aussage mit hope über eine zukünftige Wirkung.","source":"Nach Originaltest 2025 · Use of English · Item 12"},{"id":"o2025-13","year":2025,"topic":"prepositions","prompt":"He became shorter ___ his time undersea. (during / while)","answers":["during"],"explanation":"Vor der Nomengruppe his time undersea: during.","source":"Nach Originaltest 2025 · Use of English · Item 13"},{"id":"o2025-14","year":2025,"topic":"comparison","prompt":"He was able to sleep ___ better. (much / more / less)","answers":["much"],"explanation":"Much verstärkt einen Komparativ; nicht more better.","source":"Nach Originaltest 2025 · Use of English · Item 14"},{"id":"o2025-15","year":2025,"topic":"possessive","prompt":"The ___ discoveries will be presented. (scientists, Plural-Genitiv)","answers":["scientists’","scientists'"],"explanation":"Plural endet auf s → Apostroph hinter s.","source":"Nach Originaltest 2025 · Use of English · Item 15"}],"years":[{"year":2025,"listening":"Gary Anderson & das Recyclingzeichen","writing":"Die Zeitpyramide in Wemding","words":170,"page":6,"task":"JA10_GY_E_2025_Aufg.pdf","solution":"JA10_GY_E_2025_Loes_1.pdf","audio":"JA10_GY_E_2025_Hoerverst.mp3","files":["JA10_GY_E_2025_Aufg.pdf","JA10_GY_E_2025_Hoerverst.mp3","JA10_GY_E_2025_Loes_1.pdf","JA10_GY_E_2025_Loes_2.pdf","JA10_GY_E_2025_Textprod_2.pdf"],"writingText":"6 \nJahrgangsstufentest 10 Englisch 2025 – Gymnasium: Aufgaben \n \n \n \n \nThe Museum of Modern Art in New York has an online platform called “Timeless Art”. This \nplatform has started a n initiative to find examples of pioneering art from all over the world. \nAs you are fascinated by Manfred Laber's Time Pyramid, you hand in an art icle for the \nonline platform in which you outline the project and the concept of the Time Pyramid as \nwell as the fascination it holds for its viewers. Don’t forget a headline and write about 170 \nwords.  \nAlles zu seiner Zeit \nDie Wemdinger Zeitpyramide wird voraussichtlich im Jahr 3183 fertiggestellt. Alle \nzehn Jahre soll die Pyramide um einen Stein erweitert werden. Bei einer \nVeranstaltung 30 Jahre nachdem der erste Steinquader mit einem Kran auf die \nWemdinger Platte gehoben wurde, kam nun der vierte Stein hinzu. \nWer dort oben auf der Wemdinger  Platte steht und die großen Steinquader betrachtet, setzt \nsich mit dem Lauf der Zeit auseinander. Wird dieses Kunstwerk jemals fertiggestellt? Wer \nstellt es fertig? Wie viele solcher Steinsetzungen werde ich selbst noch miterleben? Wer die \nSteinblöcke der Wemdinger Zeitpyramide betrachtet, blickt in die Vergangenheit und in die \nZukunft. \nAnlässlich der 1200- Jahrfeier der Stadt Wemding wurde 1993 mit dem Bau der Pyramide \nbegonnen, und genau 30 Jahre später wurde das Kunstprojekt auf einer Hügelkuppe am \nnördlichen Stadtrand Wemdings fortgeführt. \nDie Pyramide besteht aus 120 Steinquadern mit den Maßen 1,20 Meter x 1,20 Meter x 1,80 \nMeter. Die erste Ebene soll aus 8 x 8 Steinblöcken, also 64 Steinblöcken bestehen, die \nzweite Ebene aus 36 Blöcken, die dritte Ebene aus 16 und die vierte Ebene aus vier. Die 120 \nSteinblöcke insgesamt, die jeweils im Abstand von zehn Jahren gesetzt werden, \nentsprechen somit genau dem Zeitraum von 1200 Jahren.  \nDer Künstler Manfred Laber begann 1993 mit dem Bau der Pyramide. Er wurde 1 932 in \nWemding geboren und absolvierte ein Studium der Malerei an der Hochschule der Bildenden \nKünste in Berlin, wo er 1954 seine Meisterprüfung ablegte. Auch andere Kunstwerke ließ er \nbereits von Einflüssen der Zeit und der Natur, wie Sonne und Wind, gest alten, so zum \nBeispiel seine Skulpturen und Werke auf der Insel San Antoni in Spanien. Am 17. August \n2018 verstarb Manfred Laber im Alter von 86 Jahren in Wemding. Die Steinsetzung im \nSeptember 2023 war nun die erste, die der Künstler selbst nicht mehr mit erleben konnte. \nWie die Pyramide einmal aussehen soll, legte Laber in einem Modell, welches im \nKunstMuseum Donau-Ries zu besichtigen ist, fest. \nIn Wemding gibt es einen großen Freundeskreis der Zeitpyramide, der Labers Idee \nweiterträgt. Die 2003 gegründete Stiftung „Wemdinger Zeitpyramide“ hat sich zum Ziel \ngesetzt, die Errichtung der Pyramide nach dem Konzept Manfred Labers zu fördern. Vor \nallem die Auseinandersetzung mit der Zeit – mit Vergangenheit, Gegenwart und Zukunft – ist \nes, was die Stiftungsmitgli eder an der Zeitpyramide so fasziniert. Dazu gehört auch das \n„Aushalten“, weil man nicht sehen kann, nicht wissen kann, ob sie jemals fertiggestellt wird. \nAußerdem ist es ihnen wichtig, die Idee des Kunstprojekts der Zukunft an nachkommende \nGenerationen weiterzugeben. Letztendlich wird es dadurch vom Kunst - zum \nGesellschaftsprojekt. \nFrom: https://www.donau-ries-aktuell.de/das-beste-aus-dem-blaettle/alles-zur-seiner-zeit-wemding-78357 \n (414 words, adapted, last visited: February 18, 2025) \n(Inhalt ____ / 4 BE + Sprache ____ / 6 BE) x 2 = ______ / 20 BE \n \nTotal: ______ / 50 BE \nPart III: Sprachmittlung    20 BE","total":50,"listeningMax":15},{"year":2024,"listening":"National Monuments","writing":"Das deutsche Abendbrot","words":170,"page":6,"task":"JA10_GY_E_2024_Aufg_1.pdf","solution":"JA10_GY_E_2024_Loes_1.pdf","audio":"JA10_GY_E_2024_Hoerverst.mp3","files":["JA10_GY_E_2024_Aufg_1.pdf","JA10_GY_E_2024_Ergeb.pdf","JA10_GY_E_2024_Hoerverst.mp3","JA10_GY_E_2024_Loes_1.pdf","JA10_GY_E_2024_Loes_2.pdf","JA10_GY_E_2024_Textprod.pdf","JA10_GY_E_2024_Textprod_2.pdf"],"writingText":"6 \nJahrgangsstufentest 10 Englisch 2024 – Gymnasium: Aufgaben \n \n \n  \n \nSie verbringen ein Jahr an einer englischen Schule.  In der Schülerzeitung sollen verschiedene \nArtikel zu typischen Bräuchen und Gewohnheiten der Herkunftsländer der Gastschülerinnen und \nGastschüler erscheinen.  \nBasierend auf dem vorliegenden Text schreiben Sie einen Artikel auf Englisch (ca. 170 Wörter) mit \neiner passenden Überschrift, in dem Sie das typisch deutsche Abendbrot beschreiben und seinen \nUrsprung darstellen. Gehen Sie anschließend auf die Gründe für den Trend weg vom typischen \nAbendbrot ein. Geben Sie abschließend wieder, warum dieser Brauch in Zukunft dennoch \nweiterleben wird. \n \nSchnittchendämmerung: Kommt der Untergang des Abendbrots? \n \n„Abendbrot\" wird in Deutschland oft das Abendessen genannt. Zu sich genommen wird es \nzwischen 17 und 19 Uhr. So erklären es auch Deutschlandreiseführer  oder Bücher über Deutsch \nals Fremdsprache. \nDoch in der modernen Arbeitswelt und der globalisierten Zeit des Low -Carb-Dinners – also der \nEmpfehlung vieler Ernährungsexperten, abends kohlenhydratarm zu essen – da stirbt die \nMahlzeit der Scheiben Brot mit Aufschnitt möglicherweise aus. Droht der Untergang des \nAbendbrots? Herrscht jetzt Schnittchendämmerung? \nDie Wurstindustrie gibt sich jedenfalls leicht alarmiert. Allerdings löst nicht etwa - wie man \ndenken könnte - das wachsende Angebot veganer und vegetarischer Fleischersatzprodukte \nSorgen aus. Folgenreicher sei der Wandel der Essgewohnheiten insgesamt. Statt Pausen-  oder \nAbendbrot mit Belag kämen zunehmend andere Gerichte auf die Teller.  \nDer deutsche Brauch, abends kalt zu ess en, stammt aus den 1920er Jahren. Damals dominierte \nmehr und mehr die Industrie den Alltag - im Gegensatz zu den landwirtschaftlicheren Strukturen \nin Staaten wie Italien und Frankreich. \nIn Fabriken gab es immer öfter Kantinen. Wer dort mittags speiste, wol lte abends oft kein \nwarmes Essen mehr. Da die Arbeit dank Technisierung auch körperlich weniger anstrengend \nwurde, liebten es viele am Abend leichter: Brot, Wurst, Käse, bisschen Rohkost, fertig. \nDas Abendbrot setzte sich dann nach dem Krieg noch stärker durch. Damals stieg auch die Zahl \nerwerbstätiger Frauen. Das schnell gemachte Abendbrot wurde Tradition in vielen Familien.  \nDennoch führen Millionen Deutsche heute ein Leben ohne abendliche Leberwurststulle. Die \nAllensbach-Studie „So is(s)t Deutschland\" im  Auftrag eines weltweit agierenden Nahrungsmittel -\nkonzerns förderte zutage, dass das warme Abendessen unter der Woche bei vielen inzwischen \ndie wichtigste Mahlzeit geworden ist. 2019 nannten 38 Prozent  der Deutschen das Abendessen \ndie Hauptmahlzeit des Tag es, zehn Jahre zuvor war en es noch deutlich weniger. Derzeit deutet \nalles darauf hin, dass der Megatrend zur warmen Hauptmahlzeit am Abend weitergeht.  \nDie Gießener  Künstlerin und Professorin Ingke Günther glaubt jedoch bei alledem nicht, dass \ndas früher populäre Abendbrot in Deutschland vollends verschwindet.  Es habe zwar seine \njahrzehntelang vorherrschende Rolle verloren, bei Älteren und in Familien mit Kindern ist das \nAbendbrot aber oft noch die Regel. Und in einigen städtischen Milieus, wo Bio- Bäckereien eine \nneue Brotkultur entwickelt haben, gebe es eine bewusste Rückbesinnung aufs Abendbrot.  Sie \nkommt zu dem Schluss: „Das Konzept, gemeinsam am Tisch zu sitzen und sich das Brot selbst \nzu belegen, ist einfach bestechend.  Die Bilder von einem gemeinsamen  Abendbrot sind in den \nKöpfen vieler Leute sehr lebendig.“ \nFrom: https://www.zeit.de/news/2022-03/10/schnittchendaemmerung-kommt-der-untergang-des-\nabendbrots?utm_referrer=https%3A%2F%2Fwww.google.de%2F \n (386 words, adapted, last visited: February 11, 2024) \n \n \n(Inhalt ____ / 4 BE + Sprache ____ / 6 BE) x 2 = ______ / 20 BE \n \nTotal: ______ / 50 BE \nPart III: Sprachmittlung    20 BE","total":50,"listeningMax":15},{"year":2023,"listening":"The Golden Gate Bridge","writing":"Bundesfreiwilligendienst","words":180,"page":5,"task":"JA10_GY_E_2023_Aufg.pdf","solution":"JA10_GY_E_2023_Loes.pdf","audio":"JA10_GY_E_2023_Hoerverst.mp3","files":["JA10_GY_E_2023_Aufg.pdf","JA10_GY_E_2023_Hoerverst.mp3","JA10_GY_E_2023_Loes.pdf"],"writingText":"5 \nJahrgangsstufentest 10 Englisch 2023 – Gymnasium: Aufgaben \n \n \n  \n \n \nYou are taking part in an international school project called “School’s over, what now?”, \nwhich deals with different possibilities for students after school. You have been asked to \ncontribute a text for its website about the Federal Volunteer Service in Germany.  \n \nOn the basis of the text below, write an article of about 180 words in which you give \ngeneral information on the Federal Volunteer Service, its benefits and problems.  \n \nDon’t forget to find a suitable headline for your article.  \n \nBufdi ist nicht gleich Bufdi! \n \nJede dritte Person, die einen Bundesfreiwilligendienst  (auch Bufdi genannt) macht, sich also für \neinen gewissen Zeitraum für die Allgemeinheit engagiert, bricht diesen vorzeitig ab. Aber woran \nliegt das? Die Suche nach den Ursachen ist nicht leicht , denn jeder Bundesfreiwilligendienst ist \nanders. Die Einsatzstellen können z. B. Krankenhäuser, Schulen, Altersheime, Vereine oder \nKultureinrichtungen, aber auch Bauernhöfe sein.  \nEinen Bufdi kann jede und jeder ab 16 Jahren machen, auch Ausländer können teilnehmen. Der \nDienst dauert in der Regel ein Jahr, kann aber auf sechs Monate verkürzt oder maximal auf 24 \nMonate verlängert werden. Da der Dienst freiwillig ist, muss er nicht vergütet werd en. Die \nEinsatzstellen können aber ein Taschengeld von höchstens 390 Euro festsetzen.  \nDeshalb unterscheiden sich die Umstände, unter denen die Menschen ihren Dienst leisten. Patrik \nSchnell begann seinen Bufdi in einer Kindertagesstätte – und brach ihn  nach zwei Wochen  ab. \n„Ich wollte ein wenig Berufserfahrung sammeln. Ich hatte vorher schon Praktika in derselben Kita \ngemacht.“ Doch als Bufdi war die Arbeit nicht mehr dieselbe. \n„Mir war klar, dass ich eine 40 -Stunden-Woche haben werde – und das für einen Lo hn von 250 \nEuro im Monat. Das war ok“, erzählt der 20 -Jährige heute, der Wirtschaftswissenschaften in \nKonstanz studiert. Das Problem war ein anderes: Die  Arbeit in der Kita  war nicht das, was er \nerwartet hatte.  „Ich musste vor allem putzen und aufräumen. G erade Aufgaben wie Müll \nwegbringen, 50 Lätzchen am Tag waschen und auf die Leine hängen, hätte man einfach auf alle \nMitarbeiter verteilen können, und nicht den  Bufdi alles machen lassen.“ Patrik hatte in der Kita \nnicht das Gefühl, wertgeschätzt und  fair behandelt zu werden. „ Manche Unternehmen glauben, \nsie können mit den Bufdis machen, was sie wollen. Sie setzen sie als volle Arbeitskräfte ein, \nentlohnen sie schlecht. Einen Lerneffekt gibt es nicht.“  \nGanz andere Erfahrungen hat Andreas Penzkofer gemacht. Der 20-Jährige aus München half als \nBufdi beim Erzbischöflichen Jugendamt in München  mit. Dort erledigte er vor allem \nBüroaufgaben, half bei Events  und in der  Hausaufgabenbetreuung einer offenen Einrichtung. Er \nfand die Arbeit so bereichernd, dass er seinen  Dienst von zwölf auf 18 Monate verlängerte. „Erst \nin dieser Zeit, in der ich mit Menschen zusammenarbeitete und ihnen half,  fand ich heraus, dass \nich Theologie studieren möchte – und nicht Informatik.“  Pro Monat bekam er 195 Euro \nTaschengeld, plus Pauscha len, wie etwa Fahrtkosten. Für ihn spielten die Finanzen allerdings \nkeine große Rolle, da er noch zuhause lebte.  Andreas empfand die Zeit als große persönliche \nBereicherung. „Es bringt den Freiwilligen total viel, und auch der Allgemeinheit. Es ist gut, um  \nsich in der Gesellschaft zu engagieren.“  \nGut findet Andreas auch, dass das Jahr eben freiwillig sei – dadurch könne man auch jederzeit \nabbrechen oder seinen Dienst  verkürzen, wenn man etwa ein Jobangebot  oder einen \nStudienplatz bekomme. So erklärt Andrea s sich auch die hohe Abbrecherquote. Er selbst kenne \njedoch nur einen Bufdi, der abgebrochen habe, und zwar deswegen, weil ihm eine Arbeitsstelle \nangeboten wurde.  \nAndreas beginnt nun bald sein Theologie Studium. Sein Fazit:  Ohne die Zeit als Bufdi  zwischen \nSchule und Studium hätte er seinen Weg dorthin womöglich nicht gefunden.  \nFrom: https://www.spiegel.de/politik/bundesfreiwilligendienst-bufdis-erzaehlen-weshalb-sie-abgebrochen-oder-\nverlaengert-haben-a-00000000-0003-0001-0000-000002419313 \n (501 words, adapted, last visited: February 06, 2023) \n \n(Inhalt ____ / 4 BE + Sprache ____ / 6 BE) x 2 = ______ / 20 BE \n \nTotal: ______ / 50 BE \nPart III: Sprachmittlung    20 BE","total":50,"listeningMax":15,"listeningKey":"Jahrgangsstufentest 10 Englisch 2023 – Gymnasium: Lösungen \n \n \n 2 \nPart I: Listening Comprehension          15 BE \n \nHinweise zur Durchführung: \nDer Track enthält den Hörtext zweimal  sowie sämtliche Anweisungen und Pausen. Der Track ist \nlediglich einmal abzuspielen, es dürfen durch die Lehrkraft keine Pausen gemacht werden. \n \nKorrekturhinweise: \n- Für jedes Item wird 1 BE vergeben. \n- Insgesamt werden maximal 15 BE vergeben. \n- Es dürfen halbe BE vergeben werden. \n- Rechtschreibfehler werden, sofern sie nicht sinnentstellend sind, generell nicht gewertet. \n- Wird bei den multiple-choice-Aufgaben mehr als die geforderte Anzahl von Häkchen gesetzt, \nwerden keine BE vergeben.  \n \nLehrplanbezug Jgst. 9: \n- längere, auch anspruchsvollere Äußerungen und Gespräche sowie zunehmend auch \nauthentische Hör - und Hörsehtexte (z.  B. Interviews, kurze Dokumentationen, Podcasts) in \nVarietäten der Standardsprache (auch AUS/NZ) zu unterrichts nahen Themen verstehen, die \nweitgehend bekanntes bzw. erschließbares Sprachmaterial beinhalten, auch wenn diese unter \nrealistischen Bedingungen geäußert werden. \n- den Inhalt von Texten erfassen und ihnen Global - und umfassendere Detailinformationen ent -\nnehmen, und ggf. die Absichten und Gefühlslagen der Sprecherinnen und Sprecher erkennen. \nDie Schüler innen und Schüler  sollen wesentliche Aussagen sowie Details verstehen. \nNachgewiesen werden soll das Hörverstehen explizit im Text vorkommend er Information (u. a.  \nAufgaben 1, 2) sowie die Fähigkeit, logische Rückschlüsse zu ziehen oder Information en zu \nabstrahieren (Aufgabe 7). Dabei muss nicht jedes im Text vorkommende Detail verstanden \nwerden. Das Herausfiltern wichtiger Informationen und Ignorieren irrelevanter Inhalte entspricht der \nLebenswirklichkeit. \nItem Lösung \n1 \nA problem before building: strong wind(s) / rough currents \nThe bridge was built over San Francisco Bay / Golden Gate Strait \nOpening date: May 27, 1937 \nLength: almost 2 miles \n2 \nOn opening day, people were only allowed to walk across the bridge / cross the \nbridge on foot. Since then, the Golden Gate Bridge has become one of the most \nphotographed constructions in the word.  \n3 \nReason why he and his friends hung out all night before the opening: they wanted to be \nthe first in line to cross \nTo him and his friends, crossing the bridge felt (one adjective): scary / frightening  \n4 \nWhen young Nancy Kent Danielson took the walkway over the bridge for the first time, \nshe realised that it rose (under her feet) / went up(hill) and then, after the middle, it \nlevelled off / went down again.  \n5 \n[two of the following:] \n• spoil/ruin/damage the beauty of nature \n• ruin Marin County \n• too many people  \n6 \nOn the first day the bridge was open, George Klein … \n- ran to the other end of the bridge. \n- was dressed in shorts despite the cold weather. \n7 \n[one of the following:] \n• (commuting is still) quicker \n• tourists admire scenery / priceless view of the bridge \n \n  \nQuelle des Hörtexts: https://www.npr.org/player/embed/153205217/153679340 \n(zuletzt aufgerufen am 06.02.2023, editiert)"},{"year":2022,"listening":"Höhlentaucherin Jill Heinerth","writing":"Spende dein Pfand","words":160,"page":5,"task":"JA10_GY_E_2022_Aufg.pdf","solution":"JA10_GY_E_2022_Loes.pdf","audio":"JA10_GY_E_2022_Hoerverst.mp3","files":["JA10_GY_E_2022_Aufg.pdf","JA10_GY_E_2022_Hoerverst.mp3","JA10_GY_E_2022_Loes.pdf"],"writingText":"5 \nJahrgangsstufentest 10 Englisch 2022 – Gymnasium: Aufgaben \n \n \n \n \n \nIhre AG Umweltschutz nimmt am EU -Projekt “Initiatives to  save our planet” teil. Als eine \nVorzeigeaktion stellen Sie die Initiative \"Donate your deposit - give us the money from your \nreturnable bottles\" des Hamburger Flughafens auf der englischsprachigen EU -Projekt-\nWebseite vor.   \nSchreiben Sie einen Artikel (ca . 160 Wörter) für diese Webseite, in welchem Sie die \nFunktionsweise des Projekts erklären und dessen Vorteile schildern. Zeigen Sie dabei auch \nauf, wie das Projekt das Leben von Uwe Tröger verändert hat.   \n \nHerrn Uwes Gespür für Flaschen \nJedes Jahr werden am Hamburger Flughafen mehr als eine halbe Million Plastikflaschen \nweggeworfen. Dass diese nicht im Müll landen, dafür sorgt das Projekt „Spende dein Pfand“. \nEs gibt so viel zu fühlen bei einer Flasche. Da ist die Größe, das Material – ist sie aus Glas oder \nKunststoff, hat sie dünne oder dicke Wände, und vor allem: welche Form? Uwe Tröger erkennt \n„seine Flaschen“ sogar im Dunkeln. Die, mit denen sich Geld verdiene n lässt, die dünnwandigen \nPfandflaschen aus Plastik. Da sind bis zu 25 Cent p ro Stück drin. „Das sind die wichtigsten, die \nheiligen Flaschen“, sagt er. \nFür die einen sind Flaschen Abfall. Weg damit, in den nächsten Mülleimer, am Flughafen etwa, \nbevor es durch die Sicherheitsschleuse geht und man ohnehin alle Flüssigkeiten abgeben m uss. \nFür Uwe Tröger ist so eine Flasche Teil seines Einkommens. Der 50 -Jährige arbeitet am \nHamburger Flughafen für das Projekt „Spende dein Pfand“ als Wertstoffbeauftragter, so heißt \nseine Position dort.  Pfandsammler möchte er nicht genannt werden. „ Das klingt ja so, als hätte \nich keinen Job. “ Den hat er aber. Uwe Tröger ist fest angestellt, er bezieht Mindestlohn, sein \nArbeitsvertrag ist unbefristet. Er lebt von dem, was andere Menschen wegwerfen: Plastikflaschen \nund Pfanddosen. \n„Spende dein Pfand “ startete im September 2015 in Zusammenarbeit mit dem Flughafen und \ndem Straßenmagazin „Hinz&Kunzt“. Uwe Tröger war von Anfang an dabei. Das Prinzip ist \neinfach: Durchsichtige Plastiktonnen stehen vor den Sicherheitskontrollen des Flughafens. \nPassagiere können darin ihre Pfandflaschen entsorgen. Ist eine Tonne voll, kommt Tröger mit \neiner Sackkarre vorb ei, aufladen, in ein Nebengebäude karren, sortieren. „Das ist dann ein \nbisschen so, als würde ich Fässer mit Geld durch die Gegend rollen. “ Gelegentlich steht er vor \nden Sicherheitskontrollen der Business -Class. Geschäftsreisende, die es eilig haben, könne n \nhier schneller einchecken. Manchmal, sagt Tröger, wundere er sich schon, was dort alles in den \nTonnen lande: Teure Gesichtscremes, verschlossene Cola-Dosen, sogar Essen. \nDas Projekt entstand aus einer Notlage heraus: Gesucht wurde eine Lösung für die Pfa ndflut am \nFlughafen. Pro Tag reisen hier Zehntausende Passagiere ab und hinterlassen ihre Wasser - und \nLimoflaschen. Früher landeten die einfach im Restmüll, kamen in die Müllverbrennungsanlage, \nwurden verheizt. Nun finanziert der Pfanderlös dreieinhalb Arbeitsplätze – drei Pfandbeauftragte \nund eine studentische Hilfskraft. Allein im vergangenen Jahr sammelte das Team über eine halbe \nMillion Flaschen, die jetzt auch nicht mehr die Abfalleimer verstopfen. Win-win, würde man in der \nWirtschaft sagen.  \nUwe Tröger kam sozusagen als Experte dazu. Er hielt sich mit Gelegenheitsjobs über Wasser, \nhalf bei Umzügen. Dann wurde er arbeitslos. Er hat schon früher Pfandflaschen gesammelt – an \nden Landungsbrücken am Hamburger Hafen, einem Hotspot für Touristen. „Das ging zu der Zeit \nnoch ganz gut“, erinnert er sich. Mittlerweile seien aber viele Sammler unterwegs, das Geschäft \nlohne sich kaum noch. Die Flut von  Pfandsammlern sei ein Zeichen von Armut, sagt  Stephan \nKarrenbauer, Sozialpädagoge beim Straßenmagazin „Hinz&Kunzt“: „Man kann heute nicht mehr \nsagen: Das machen nur die Obdachlosen “, erklärt er, „Heute sammeln auch Rentner, Früh -\nRentner oder Osteuropäer.“ Nicht bei allen stehe dabei der Geldaspekt im Vordergrund. „Einige \nsehnen sich auch nach einem geregelten Tagesablauf, nach einer sinnvollen Aufgabe. Einfach \nmal wieder unter Menschen zu kommen.“ \nFrom: https://www.stern.de/wirtschaft/muell/spende-dein-pfand--unterwegs-mit-einem-pfandsammler-am-flughafen-\n7865262.html (483 words, adapted, last visited: August 20, 2020) \n \n(Inhalt ____ / 4 BE + Sprache ____ / 6 BE) x 2 = ______ / 20 BE \n \nTotal: ______ / 50 BE \nPart III: Sprachmittlung    20 BE","total":50,"listeningMax":15,"listeningKey":"Jahrgangsstufentest 10 Englisch 2022 – Gymnasium: Lösungen \n \n \n 2 \nPart I: Listening Comprehension          15 BE \n \nHinweise zur Durchführung: \nDer Track enthält den Hörtext zweimal  sowie sämtliche Anweisungen und Pausen. Der Track ist \nlediglich einmal abzuspielen, es dürfen durch die Lehrkraft keine Pausen gemacht werden. \n \nKorrekturhinweise: \n- Insgesamt werden maximal 15 BE vergeben. \n- Es werden nur ganze BE vergeben. \n- Werden bei multiple-choice-Aufgaben mehr als die angegebene Zahl von Lösungen ange -\nkreuzt, so werden auf die entsprechende Aufgabe keine BE vergeben.  \n- Rechtschreibfehler führen, sofern sie nicht sinnentstellend sind, nicht zum Abzug von BE. \n \nLehrplanbezug Jgst. 9: \n- längere, auch anspruchsvollere Äußerungen und Gespräche sowie zunehmend auch \nauthentische Hör - und Hörsehtexte (z.  B. Interviews, kurze Dokumentationen, Podcasts) in \nVarietäten der Standardsprache (auch AUS/NZ) zu unterrichtsnahen  Themen verstehen, die \nweitgehend bekanntes bzw. erschließbares Sprachmaterial beinhalten, auch wenn diese unter \nrealistischen Bedingungen geäußert werden. \n- den Inhalt von Texten erfassen und ihnen Global - und umfassendere Detailinformationen ent -\nnehmen, und ggf. die Absichten und Gefühlslagen der Sprecherinnen und Sprecher erkennen. \nDie Schüler 1 sollen wesentliche Aussagen sowie Details verstehen. Nachgewiesen werden soll \ndas Hörverstehen explizit im Text vorkommend er Information (u. a. Aufgaben 1, 2) sowie  die \nFähigkeit, logische Rückschlüsse zu ziehen oder Informationen zu abstrahieren (Aufgabe 7). Dabei \nmuss nicht jedes im Text vorkommende Detail verstanden werd en. Das Herausfiltern wichtiger \nInformationen und Ignorieren irrelevanter Inhalte entspricht der Lebenswirklichkeit. \n \nItem Lösung \n1a 2001 \n1b Canadian \n1c (underwater) filmmaker \n2a B 15 \n2b (comparable to the size of) Jamaica \n2c Antarctic \n3a \nbelow zero / -1.8* (degrees) / was too/very/extremely/freezing cold \n[* -1,8 degrees wird im Hörverstehen in Anlehnung an Orthographiefehler akzeptiert, \nmuss aber in allen anderen Aufgabenformen als Fehler im Sinne der interkulturellen \nKompetenz sanktioniert werden.] \n3b cold water experience \n4  dry/wet suits \n lights / flashlights / torches \n5 d)  colourful. \ne)  surprising. \n6 c)  spider-like creatures \n7 a)  takes fewer risks when diving. \nd)  wants to draw attention to how the area is changing. \n \n  \nQuelle des Hörtexts: https://www.bbc.co.uk/sounds/play/w3csyhz5 (zuletzt aufgerufen am \n18.12.2021, 3:50; editiert) \n \n \n \n                                                           \n1 Der Kürze halber ist im Text von „Schülern“ die Rede. Dass die Schülerschaft aus Buben und Mädchen \nbesteht, wurde überall mit bedacht."},{"year":2021,"listening":"Little Free Library","writing":"Klassenzimmer unter Segeln","words":160,"page":4,"task":"JA10_GY_E_2021_Aufg.pdf","solution":"JA10_GY_E_2021_Loes.pdf","audio":"JA10_GY_E_2021_Hoerverst.mp3","files":["JA10_GY_E_2021_Aufg.pdf","JA10_GY_E_2021_Hoerverst.mp3","JA10_GY_E_2021_Loes.pdf"],"writingText":"Jahrgangsstufentest 10 Englisch 2021 – Gymnasium: Aufgaben   \n 4 \nPart III: Sprachmittlung 20 BE \n \nIhre Schule nimmt an einem EU -Wettbewerb zum Thema Exploring the world  teil. \nVerfassen Sie auf Basis des vorliegenden Textes einen englischsprachigen Artikel \n(Umfang ca. 1 60 Wörter), der das Projekt „Klassenzimmer unter Segeln“ vorstellt.  \nErläutern Sie die Grundzüge dieses Projekts und beschreiben Sie, wie man daran \nteilnehmen kann, wie der Alltag auf dem Schiff aussieht und auf was man bereit sein muss \nzu verzichten. Finden Sie eine treffende Überschrift.  \n \nKLASSENZIMMER UNTER SEGELN \n \nSchülerin Anna (15) war wie gebannt, als ihr im Juli 2016 ein Zeitungsartikel in die Hände fiel, in dem \nes um das Programm „Klassenzimmer unter Segeln“ ging: 34 Schüler der zehnten Jahrgangsst ufe \nfolgen auf einem Segelschiff den Spuren großer Entdecker. Sechs Monate, in denen die Jugendlichen \naus ganz Deutschland in Begleitung von Profis nicht nur den Atlantik überqueren, sondern auch Berge \nbesteigen, im Dschungel übernachten und Ureinwohner ke nnenlernen. „Ich war total fasziniert“, \nberichtet Anna.  \nZwischen 150 und 200 Schüler haben sich für die 34 Plätze bei der Expedition, die von der Friedrich -\nAlexander-Universität Erlangen-Nürnberg durchgeführt wird, beworben. Ein großer Ansturm auf die \nThor Heyerdahl, so heißt das Segelschiff. Doch mit ihrem Motivationsschreiben hat Anna die \nOrganisatoren von sich überzeugen können. Sie war unter den 50 Auserwählten, die zu einer \nProbewoche eingeladen wurden.  \nNeben den Schülern gehören zur Schiffsmannschaf t auch fünf Lehrer. Der Rest sind seebewährte \nProfis, neben dem Kapitän unter anderem auch ein Bootsmann und ein Bordarzt. Insgesamt besteht \ndie Mannschaft aus 50 Personen – darunter auch Anna. Sie wurde in das Projekt aufgenommen, weil \nsie in der Probewoc he zeigte, dass sie die erforderlichen Voraussetzungen mitbrachte. Teamfähig \nmussten die Bewerber sein, begeisterungsfähig, neugierig und aufgeschlossen für Neues. \nAuf dem Segeltörn sind auch 75 Landtage eingeplant. Die Schüler legen zum Beispiel auf den \nBermudas an. Besonders aber freut sich Anna auf die San -Blas-Inseln, die vor Panama liegen. „Die \nsind der Prototyp der einsamen Insel“, berichtet Anna. Und was nimmt sie mit auf ihre einsame Insel? \nDa muss Anna keine Sekunde nachdenken. „Meine Kamera – unbedingt!“ Auf vieles andere muss die \n15-Jährige hingegen verzichten. Neben einem Tagesrucksack darf sie einen 100 -Liter-Seesack mit an \nBord nehmen. Von den Organisatoren gibt es eine Packliste, daran können sich die Nachwuchs -\nSegler orientieren. Ganz o ben dabei: Ölzeug. „Das sind ganz dicke und  robuste Regenjacken und       \n-hosen.“ Viel Platz für Luxus bleibt nicht im Gepäck. Die Jugendlichen müssen auf hoher See ohne \nMobiltelefone auskommen. So steht es im Bordregelregister. „Die Handys werden eingesa mmelt. Erst \nwenn wir an Land gehen und uns dort akklimatisiert haben, bekommen wir sie wieder, damit wir auch \nunsere Eltern und Freunde kontaktieren können“, berichtet Anna. Die ersten drei Wochen haben die \nSchüler Zeit, um sich auf dem Schiff einzuleben u nd an den Bordalltag zu gewöhnen. Danach werden \nzwei Gruppen gebildet, die abwechselnd je einen Tag am Schiffsbetrieb und am Unterricht \nteilnehmen. So bekommen die Matrosen etwa 40 Prozent des normalen Schulstoffs mit. Freilich lernt \nAnna auf der Reise une ndlich viel mehr. Allein an Bord werden Praktika beim Bootsmann und \nProviantmeister durchlaufen. \nAm 14. Oktober läuft die Thor Heyerdahl aus. Die Vorfreude steigt, aber auch erste Bedenken machen \nsich bei Anna breit. War es die richtige Entscheidung? Und w ie hart wird die Trennung von den \nEltern? Da hilft es, dass Mama und Papa zu 100 Prozent hinter der Entscheidung ihrer Tochter \nstehen. „Das ist ein sehr gutes Gefühl“, betont Anna. „Trotzdem werden beim Abschied bestimmt ein \npaar Tränen fließen.“ \nFrom: https://www.merkur.de/lokales/freising/freising-ort28692/anna-hisst-segel-freisinger-schuelerin-fuer-sechs-monate-\nauf-hoher-see-10322205.html (adapted; last visited: June 12, 2019) \n(Inhalt ____/ 4 BE + Sprache ____/ 6 BE) x 2 = _____ / 20 BE \n \nTotal: _____ / 50 BE","total":50,"listeningMax":15,"listeningKey":"Jahrgangsstufentest 10 Englisch 2021 – Gymnasium: Lösungen \n2 \nPart I: Listening Comprehension 15 BE \nHinweise zur Durchführung: \nDer T rack enthält den Hörtext zweimal  sowie sämtliche Anweisungen und Pausen. Der \nTrack ist lediglich einmal abzuspielen, es dürfen durch die Lehrkraft keine Pausen gemacht \nwerden. \nKorrekturhinweise: \n- Insgesamt werden maximal 15 BE vergeben. \n- Es ist möglich, halbe BE zu vergeben. \n- Rechtschreibfehler führen, sofern sie nicht sinnentstellend sind, nicht zum Abzug von \nBE. \nLehrplanbezug Jgst. 9: \n- längere Äußerungen und Gespräche in natürlichem Sprechtempo zu einem breiteren \nThemenspektrum global und in wichtigen Details verstehen, sofern vorwiegend in \nbritischer bzw. amerikanischer Standardsprache gesprochen wird  \n- längere, auch authentische Hörtexte zu bekannten Themen global und ggf. im Detail \nverstehen \nDie Schüler1 sollen wesentliche Aussagen sowie Details verstehen. Nachgewiesen werden \nsoll das Hörverstehen explizit im Text vorkommender Information (u. a. Aufgaben 2 , 5) \nsowie die Fähigkeit, logische Rückschlüsse zu ziehen oder Informationen zu abstrahieren \n(Aufgabe 1). Dabei muss nicht jedes im Text vorkommende Detail verstanden werden. Das \nHerausfiltern wichtiger Informationen und Ignorieren irrelevanter Inhalte entspricht der \nLebenswirklichkeit. \nItem Key \n1 d (who try to solve general problems they are confronted with in their \ncommunities.) \n2a non-profit (organization) \nHinweis: (with) no profit akzeptieren \n2b anyone can take a book or leave a book / anyone can exchange books \nHinweis: nur take a book oder nur leave a book ist nicht ausreichend, da das \nSystem der „Free Library“ sonst nicht funktionieren würde \n3a south-east coast (Hinweis: nur south bzw. east coast nicht akzeptabel) \n3b children/kids \n3c square \n3d sign/do anything \n4 b) Many locals participated in creating the “Little Free Library”.\ne) There are always enough books in the “Little Free Library”.\n5a Two of the following: \n wide variety of people coming through the square / many people walk by\n direct access from main road/beach\n right by/next to a bus stop\n5b (just over) 1 year \n5c positive / people love it \n5d Two of the following: \n things that shouldn’t be left in there would be left in there\n (becomes) obsolete / people lose interest\n (gets) vandalized/destroyed / needs a lot of repairing\n have to restock it a lot\nHinweis: system doesn’t work ist als Lösung zu global (Weltwissen) und gilt daher \nnicht \n1 Der Kürze halber ist im Text von „Schülern“ die Rede. Dass die Schülerschaft aus Buben und \nMädchen besteht, wurde überall mit bedacht."},{"year":2019,"listening":"Instagram & Naturtourismus","writing":"Herman ze German","words":160,"page":4,"task":"JA10_GY_E_2019_Aufg.pdf","solution":"JA10_GY_E_2019_Loes.pdf","audio":"JA10_GY_E_2019_Hoerverst.mp3","files":["JA10_GY_E_2019_Aufg.pdf","JA10_GY_E_2019_Hoerverst.mp3","JA10_GY_E_2019_Loes.pdf"],"writingText":"Jahrgangsstufentest 10 Englisch 2019 – Gymnasium: Aufgaben   \n 4 \nShirley regularly speaks out about the hardship she must face \nin her early working days. If she didn’t use the nickname \nSteve professionally then, she wouldn’t have won contracts \nwhen people thought they are dealing with a man.  \n_________________________ \n_________________________ \n \n_________________________ \n \nFrom: https://www.theguardian.com/technology/2017/aug/20/[...] (adapted) \n              BE \n \n \nPart III: Mediation 20 BE \n \n \nLokal Herman ze German in London \nAzadeh Falakshahi und Florian Frey hatten eigentlich ganz andere Pläne: Sie zog vor neun Jahren nach Brighton, \num Fotografie zu studieren. Er kam der Liebe wegen nach und arbeitete als Friseur. Nun eröffnet das Paar in \nLondons schicker Charlotte Street bereits das dritte Lokal. Bei Herman ze German gibt es Würste aus ihr em \nHeimatort im Schwarzwald - und die Briten können nicht genug davon bekommen. \nZur Lunchtime bilden sich in den ersten beiden Shops in Soho oder am Bahnhof Charing Cross regelmäßig lange \nSchlangen. Die Kunden lieben die Würste, bei jedem zweiten hapert es  dennoch an der Bestellung. \"Can I get a, \neh..., Brockwurst?\", stammelt ein Banker - unsicher, ob er eine Brat- oder eine Bockwurst nehmen sollte. \nDeutschland ist in London angesagt wie nie  \nMit dem dritten Laden nähert sich das Paar nun einer neuen Größen ordnung: mehr als 50 Sitzplätze auf zwei \nEtagen - und jede Menge etablierte Konkurrenz in der Nachbarschaft. Das Risiko ist dennoch gering. \nDeutschland ist auf der Insel angesagt wie nie - und damit auch seine Speisen.  \n\"Der Hype hat sicher viele Gründe. B erlin spielt da eine große Rolle, aber es liegt auch daran, dass uns \nDeutschen und Engländern so langsam bewusst wird, dass wir gar nicht so unterschiedlich sind, wie wir immer \ntun\", sagt Falakshahi.  \nIn den Läden spielen Falakshahi und Frey mit den Klischees und schaffen es dabei, cool zu sein. Die Wände sind \nmit Fleischwölfen dekoriert. Aus den Lautsprechern auf den Toiletten erklingen deutsche Märchen. Und im \nFenster steht ein Schild: \"Yes, we really are German\". \"Weil wir nicht den Stereotypen entsprech en, hat uns das \nam Anfang niemand geglaubt\", sagt Falakshahi, die im Alter von zweieinhalb Jahren mit ihrer Familie aus Iran \nnach Süddeutschland übergesiedelt ist. \nVon der ersten bis zur zweiten Eröffnung dauerte es drei Jahre. Zwischen Herman 2 und Herman  3 verging nur \neins. In den nächsten zwölf Monaten sollen zwei bis drei weitere Lokale dazukommen. Läuft alles nach Plan, \nwird es die Würste von Metzger Hug aus Steinen mit dem Herman -ze-German-Logo bald auch in englischen \nSupermärkten geben.  \n\"Bratwurstwochen\" im Pub und ein Verkaufswagen für Festivals  \n\"Die englischen Würste sind nicht schlecht, aber nicht mit deutschen zu vergleichen\", sagt Frey. Schon bald \nkamen aus der Heimat Carepakete und im Kofferraum von Freunden wurde Wurst nach England geschmugge lt. \nIn der eigenen WG teilte das Paar seine Leidenschaft zunächst bei Grillabenden mit Freunden. Es folgten \n\"Bratwurstwochen\" im Pub an der Ecke. Dort wurde eine Agentur aufmerksam und fragte, ob die beiden ihre \nWürste nicht auf einem Musikfestival anbiete n wollen. Die Entscheidung fiel aus dem Bauch. \"Wir haben \nimprovisiert und die ganze Nacht vorher Zwiebeln geschnitten\", sagt Falakshahi. Am nächsten Tag gingen alle \n6000 Würste weg.  \nZwei Jahre tingelten Falakshahi und Frey über Festivals, bevor sie 2010 ihr erstes Restaurant eröffneten – für \nzwei Tage, dann verrammelten sie wieder die Tür. \"Wir waren viel zu langsam. Für uns war das auch learning by \ndoing\", sagt Falakshahi heute. Zwei Tage später kam es zur Neueröffnung. Bis heute läuft der Laden \nreibungslos. \nFrom: http://www.spiegel.de/reise/staedte/london-deutsches-lokal-herman-ze-german-eroeffnet-neue-filiale-a-995974.html \n (adapted; last visited: March 12, 2019) \n\n\n\n  Jahrgangsstufentest 10 Englisch 2019 – Gymnasium: Aufgaben   \n 5 \n \nIhr englischer Freund sucht nach einem Ferienjob in der Gastronomie in London. Sie haben den  \nArtikel über das Restaurant  Herman ze German  neulich in der Zeitung gelesen und schlagen ihm \ndieses vor. Um ihn besser auf die Bewerbung vorzubereiten, gehen Sie in Ihrer englischen E -Mail \n(ca. 160 Wörter) auf folgende Punkte ein:  \n- wie es zu der Idee und dem ersten Herman ze German Restaurant kam \n- warum die Restaurants in London so beliebt sind und  \n- welche Pläne die beiden Besitzer für die Zukunft haben. \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n_____________________________________________________________________________ \n (Inhalt ____ BE + Sprache ____ BE) x 2 =               BE \nTotal:               BE","total":49,"listeningMax":14,"listeningKey":"Jahrgangsstufentest 10 Englisch 2019 – Gymnasium: Lösungen   \n 2 \nPart I: Listening Comprehension 13 BE \n \n \nHinweise zur Durchführung: \n- Track 1 der CD enthält den Hörtext zweimal, sowie sämtliche Anweisungen und \nPausen. Track 1 der CD ist lediglich einmal abzuspielen, es dürfen durch die \nLehrkraft keine Pausen gemacht werden. \n- Track 2 enthält die Hörverstehensaufgabe für Jgst. 6. \n \nKorrekturhinweise: \n- Insgesamt werden maximal 14 BE vergeben. \n- Es werden nur ganze BE vergeben. \n- Rechtschreibfehler führen, sofern sie nicht sinnentstellend sind, nicht zum Abzug von \nBE. \n \nLehrplanbezug Jgst. 9: \n- längere Äußerungen und Gespräche in natürlichem Sprechtempo zu einem breiteren \nThemenspektrum global und in wichtigen Details verstehen, sof ern vorwiegend in \nbritischer bzw. amerikanischer Standardsprache gesprochen wird  \n- längere, auch authentische Hörtexte zu bekannten Themen global und ggf. im Detail \nverstehen \nDie Schüler 1 sollen wesentliche Aussagen sowie Details verstehen. Nachgewiesen wer den \nsoll das Hörverstehen explizit im Text vorkommend er Information (u. a. Aufgaben 1, 4 ) \nsowie die Fähigkeit, logische Rückschlüsse zu ziehen oder Information en zu abstrahieren  \n(Aufgabe 5). Dabei muss nicht jedes im Text vorkommende Detail verstanden werd en. Das \nHerausfiltern wichtiger Informationen und Ignorieren irrelevanter Inhalte entspricht der \nLebenswirklichkeit. \nItem Key \n1a loving nature to death \n1b travel photographer (photographer alleine nicht ausreichend)  \n1c Chicago \n2 they draw big crowds / too many visitors / overcrowding / more popular than other \nsites \n3a (northern) Arizona  \n3b (complete) 180 degree turn \n3c a thousand feet deep \n4 a parking lot / a viewing platform \n5a false \n5b false \n5c true (according to the text – in fact at 347 feet in height it is the second tallest \nrailroad arch in the US) \n5d false \n6 two of the following: vandalism / graffiti / (camp)fires (that caught the bridge) \n \n \nQuelle des Hörtexts: https://www.npr.org/2017/11/12/563398606/instagram-crowds-may-\nbe-ruining-nature (zuletzt aufgerufen am 21.09.2018, 3:27; editiert) \n \n \n                                                           \n1 Der Kürze halber ist im Text von „Schülern“ die Rede. Dass die Schülerschaft aus Mädchen und Jungen \nbesteht, wurde überall mit bedacht."},{"year":2018,"listening":"Originalaufgaben ohne Hördatei","writing":"Jugend hackt","words":150,"page":5,"task":"JA10_GY_E_2018_Aufg.pdf","solution":null,"audio":null,"files":["JA10_GY_E_2018_Aufg.pdf"],"writingText":"Jahrgangsstufentest 10 Englisch 2018 – Gymnasium: Aufgaben   \n 5 \nHolt die Hacker-Talente aus den Kinderzimmern \nKinder, die gerne programmieren, haben es schwer in Deutschland. Die Macher von Jugend \nhackt wollen das ändern.   \nAls Franziska Paulus ein paar Freundinnen beim Turnen zum ersten Mal von ihrem anderen \nHobby erzählte, guckten die verständnislos. \"Du programmierst? Das ist doch total langweilig.\" \nDas findet die 17-Jährige nicht. Ihr macht es Spaß, logisch zu denken, Neues zu entwickeln.  \n„Eltern, die erkennen, dass ihr Kind gerne programmiert, werden in Deutschland oft hilflos \nzurückgelassen\", sagt die Politikwissenschaftlerin Maria Schröder. „Sie sind verunsichert, weil ihr \nKind etwas kann, das sie selbst nicht nachvollziehen können.\" – Schröder bezieht sich auf Kinder \nund Jugendliche wie Franziska Paulus, die ihrer Meinung nach noch zu wenig unterstützt werden. \nDeshalb hat sie mit der Open Knowledge Foundation im vergangenen Jahr das Projekt  Jugend \nhackt initiiert. Dort kommen Jugendliche zwischen zwölf und achtzehn zusammen, um \ngemeinsam zu programmieren, unterstützt von ehrenamtlichen Helfern.  \nDas Interesse war größer als erwartet und erhofft. Nach fünf Wochen hatten sich immerhin 50 \nJugendliche über die Jugend-hackt-Seite für den Wochenendkurs angemeldet. Das liegt laut \nSchröder auch daran, dass es in Deutschland kaum Angebote für Jugendliche gibt, die sich mit \nSoftware-Entwicklung beschäftigen.  \nDie Teenager bei Jugend hackt sollen sich im Team neue K enntnisse aneignen. Aber genauso \nwichtig sei es zu lernen, dass sie ihre technischen Fähigkeiten auch nutzen können, um etwas \nPositives zu bewirken, sagt Schröder. Denn „sie haben die Macht, unsere Gesellschaft zu \nverändern.\"  \nAn dem Camp, das letztes Jahr  erstmals in Berlin junge Programmierer zusammenbrachte, hat \nFranziska teilgenommen. Aus ganz Deutschland reisten  Talente an. Viele der 63 Jugendlichen \nwaren anfangs überfordert, denn sie sollten sich Projekte ausdenken und umsetzen, unterstützt \nzwar von e hrenamtlichen Mentoren, aber selbstständig und auf Grundlage eigener Ideen. Das \nwaren viele aus der Schule nicht gewöhnt, sagt Maria Schröder.  \nFranziska hat mit einer Freundin und einem ihnen vorher unbekannten Jungen eine Website \nprogrammiert, auf der man Trinkbrunnen in der Umgebung finden kann. Auf die Idee kam sie, weil \nsie in den Sommerferien in München war und festgestellt hatte, dass es dort sehr viele \nTrinkbrunnen gibt, aber kaum ein Tourist wusste, wo man sie findet.  \nVor der Veranstaltung meldete n sich einige teils besorgte, teils begeisterte Eltern bei Maria \nSchröder. Sie waren wegen des Namens irritiert. „Ist Hacken nicht was Böses?\" wollten sie \nwissen. Dabei diente Hacken ursprünglich der Wissensaneignung und der kreativen Tätigkeit: \nMan nimmt etwas auseinander, um zu verstehen, wie es funktioniert.    \nMaria Schröder konnte den meisten Eltern begreiflich machen, dass ihre Veranstaltung kein \nEvent zur Heranzüchtung von kriminellen Jugendlichen ist, sondern das Gegenteil: Eine \nZusammenkunft junger Menschen, die sich überlegen, wie sie das, was sie können, sinnvoll für \ndie Gesellschaft einsetzen. Jugend hackt ist zudem ein geschützter Raum, in dem sich Menschen \nmit denselben Interessen treffen, die sich sonst nur online begegnen würden.  \nMaria Schröder würde gerne mehr Kindern die Möglichkeit geben, an Jugend hackt teilzunehmen. \nAber noch kann sich die Open Knowledge Foundation nur eine Veranstaltung pro Jahr leisten und \nauch das nur knapp. Denn es fehlen Sponsoren. Die Generation mit dem Geld, die G eneration, \ndie Angst vor kriminellen Hackern hat, versteht noch nicht, wie klug diejenigen sind, die da vor \nihren Laptops sitzen.  \nFrom: http://www.zeit.de/digital/internet/2014-05/jugend-hackt-projekt-republica/komplettansicht \n (adapted; last visited: March 7, 2018)","total":50,"listeningMax":15}],"listeningItems":{"2025":[["Year of the invention","1970"],["His age","23"],["Subject he studied","architecture"],["What he saw on campus","a poster / an ad"],["What contestants were asked to submit","a logo for recycled paper products"],["Two reasons for taking part (task 3)","b and e: no special plans; no particular equipment needed"],["Correct statement in task 4","a: less than a full day for the major job"],["Symbol in task 5 (see PDF)","c"],["What he received after a while","a letter / confirmation that he had won"],["Prize money in dollars","2,000"],["Why he used it for studying","It had to be used to further his education."],["Institution","University of Stockholm"],["Correct picture in task 7 (see PDF)","b"],["What makes him proud","His work raised awareness of recycling."]],"2024":[["One reason for the decision","protection from development / keeping places open for recreation"],["Nickname of Avi Kwa Ame","Spirit Mountain"],["Size in acres","(over) 450,000"],["Exact location","southern Nevada"],["Two features of the landscape","Any two: desert, rocky area, mountains, wide landscapes, forests, desert plants / vegetation"],["One animal besides bighorn sheep","desert tortoise / lizards"],["Why the place matters to tribal groups","historical artifacts / origin or creation stories / a sacred place"],["Army shooting practice until which decade?","1960s"],["Colour / kind of flowers","yellow / poppy"],["Type of landscape","desert"],["An outdoor activity besides camping","hiking"],["Correct statement in task 5","It is not yet safe to visit."],["Two correct statements in task 6","He wants to declare several sites national monuments; community groups pushed him to designate these two sites."]]},"plan":[["16.09.","Lernstand entdecken","12 kurze Fragen. Notiere zwei Themen, die du wiederholen möchtest.","diagnostic",15],["17.09.","Zeiten auffrischen","Simple past, present perfect und progressive unterscheiden.","topic:tenses",20],["18.09.","Gerund & Infinitiv","Verbverbindungen lernen, dann gezielt üben.","topic:ing",20],["19.09.","Genau hinhören","Original-Hörverstehen 2021 bearbeiten und abgleichen.","listening:2021",25],["20.09.","If-Sätze & indirekte Rede","Erst Regeln nachlesen, dann die Lücken füllen.","topic:conditionals",20],["21.09.","Originaltraining 2022","15 Grammatikaufgaben, anschließend Fehler verstehen.","year:2022",20],["22.09.","Informationen vermitteln","Sprachmittlung 2023 planen, schreiben und selbst prüfen.","writing:2023",30],["23.09.","Passiv & Partizipien","Aktive und passive Bedeutung unterscheiden.","topic:participles",20],["24.09.","Originaltraining 2024","Grammatik üben und die zugehörigen Regeln nutzen.","year:2024",20],["25.09.","Listening 2025","Mit dem aktuellen Übungsformat vertraut werden.","listening:2025",25],["26.09.","Deine Fehlerwerkstatt","Falsch gelöste Aufgaben noch einmal ohne Hilfe lösen.","mistakes",20],["27.09.","Generalprobe 2025","Ein kompletter Originaltest unter Zeitbedingungen.","exams:2025",60],["28.09.","Ruhig wiederholen","Fehler ansehen, Signalwörter wiederholen, rechtzeitig Schluss machen.","mistakes",15]]};
